    #[test]
    fn legacy_scenario_and_definition_scripts_preserve_native_bytes() {
        let dir = tempdir().expect("tempdir");
        let scenario_dir = write_resilience_fixture(dir.path(), None, "// replaced below\n");
        std::fs::write(
            scenario_dir.join("Script.c"),
            [
                b"#strict\nglobal func Initialize() { Message(\"".as_slice(),
                &[0xe9, 0xff],
                b"\"); }\n",
            ]
            .concat(),
        )
        .expect("write raw scenario script");

        let definition_dir = dir.path().join("Defs.c4d/Good.c4d");
        std::fs::write(
            definition_dir.join("Script.c"),
            b"#strict\nfunc RawLabel() { return \"$RawLabel$\"; }\n",
        )
        .expect("write definition script");
        std::fs::write(
            definition_dir.join("StringTblUS.txt"),
            [b"RawLabel=".as_slice(), &[0xe9, 0xff], b"\n"].concat(),
        )
        .expect("write raw definition string table");

        let resolver = FileSystemResolver {
            roots: vec![dir.path().to_path_buf()],
        };
        let scenario =
            Scenario::load_from_path_with(&scenario_dir, &resolver).expect("scenario loads");
        assert!(scenario
            .script
            .as_ref()
            .is_some_and(|script| clonk_script::c4_string_bytes(&script.source).contains(&0xff)));

        let mut engine = Engine::with_seed(0);
        scenario.apply(&mut engine).expect("raw scripts compile");
        let snapshot = engine.snapshot();
        assert_eq!(
            clonk_script::c4_string_bytes(&snapshot.hud.messages[0].lines[0]),
            [0xe9, 0xff]
        );

        let object = engine
            .spawn_object(SpawnConfig::new("GOOD"))
            .expect("GOOD spawns");
        let index = engine.find_object_index(object).expect("GOOD index");
        let value = engine
            .call_object_function(index, "RawLabel", Vec::new())
            .expect("localized raw definition function runs");
        assert_eq!(
            value,
            clonk_script::Value::String(clonk_script::c4_string_from_bytes(&[0xe9, 0xff]).into())
        );
    }

    #[test]
    fn legacy_definition_script_localizes_unquoted_array_values() {
        // C4Def::Load gives each definition script its local StringTbl and
        // C4ScriptHost::MakeScript replaces `$key$` across the whole source
        // before Preparse (C4Def.cpp:625-633; C4ScriptHost.cpp:46-82).
        // Hazard's HHKS definition relies on an unquoted key expanding to a
        // C4Script array literal (Killstats.c4d/StringTblUS.txt:1-6).
        let dir = tempdir().expect("tempdir");
        let scenario_dir = write_definition_localization_fixture(
            dir.path(),
            "#strict\nfunc Messages() { return $Messages$; }\n",
            "Messages=[\"first\",\"second\"]\n",
        );
        let resolver = FileSystemResolver {
            roots: vec![dir.path().to_path_buf()],
        };

        let scenario =
            Scenario::load_from_path_with(&scenario_dir, &resolver).expect("scenario loads");
        let definition = scenario
            .definitions
            .iter()
            .find(|definition| definition.id == "GOOD")
            .expect("GOOD definition exists");

        assert!(definition.script.contains("return [\"first\",\"second\"]"));
        assert!(!definition.script.contains("$Messages$"));
        let mut engine = Engine::with_seed(0);
        scenario
            .apply(&mut engine)
            .expect("localized definition compiles");
        let id = engine
            .spawn_object(SpawnConfig::new("GOOD"))
            .expect("GOOD spawns");
        let index = engine.find_object_index(id).expect("GOOD object index");

        assert_eq!(
            engine
                .call_object_function(index, "Messages", Vec::new())
                .expect("Messages runs"),
            clonk_script::Value::Array(vec![
                clonk_script::Value::String("first".to_string().into()),
                clonk_script::Value::String("second".to_string().into()),
            ])
        );
    }

    #[test]
    fn legacy_scenario_script_respects_language_order() {
        // C4ComponentHost tries each LanguageEx code in order after the
        // unsuffixed StringTbl.txt candidate (C4ComponentHost.cpp:65-89;
        // C4Components.h:56).
        let dir = tempdir().expect("tempdir");
        let scenario_dir = write_resilience_fixture(
            dir.path(),
            None,
            "#strict\nglobal func Localized() { return \"$MsgIntro2a$\"; }\n",
        );
        std::fs::write(
            scenario_dir.join("StringTblUS.txt"),
            "MsgIntro2a=Come with me, princess!\n",
        )
        .expect("write US string table");
        std::fs::write(
            scenario_dir.join("StringTblDE.txt"),
            "MsgIntro2a=Komm mit mir, Prinzessin!\n",
        )
        .expect("write DE string table");
        let resolver = FileSystemResolver {
            roots: vec![dir.path().to_path_buf()],
        };

        let scenario =
            Scenario::load_from_path_with_languages(&scenario_dir, &resolver, &["DE", "US"])
                .expect("scenario loads");
        let script = &scenario.script.as_ref().expect("scenario script").source;

        assert!(script.contains("\"Komm mit mir, Prinzessin!\""));
        assert!(!script.contains("\"Come with me, princess!\""));
    }

    #[test]
    fn scenario_script_assembly_uses_all_c4cfn_script_segments_in_language_order() {
        fn loaded_source(
            root: &std::path::Path,
            scenario_dir: &std::path::Path,
            languages: &[&str],
        ) -> String {
            let resolver = FileSystemResolver {
                roots: vec![root.to_path_buf()],
            };
            Scenario::load_from_path_with_languages(scenario_dir, &resolver, languages)
                .expect("scenario components load")
                .script
                .expect("scenario host exists")
                .source
        }

        // A scenario may consist only of a localized Script{}.c component;
        // each LanguageEx segment is narrowed to two native bytes.
        let localized = tempdir().expect("localized tempdir");
        let localized_scenario = write_resilience_fixture(localized.path(), None, "// remove me\n");
        std::fs::remove_file(localized_scenario.join("Script.c")).expect("remove base script");
        std::fs::write(
            localized_scenario.join("ScriptDE.c"),
            b"// $Assembly$\0ignored localized tail",
        )
        .expect("write localized-only script");
        std::fs::write(
            localized_scenario.join("StringTblDE.txt"),
            b"Assembly=localized only\n",
        )
        .expect("write two-byte-code string table");
        std::fs::write(
            localized_scenario.join("ScriptOld.c"),
            b"// must stay excluded",
        )
        .expect("write unrelated script");
        let source = loaded_source(localized.path(), &localized_scenario, &["DE-extra", "US"]);
        assert_eq!(
            clonk_script::c4_string_bytes(&source),
            b"\n// localized only"
        );

        // The preferred ScriptDE.c exists but is not readable as a file, so
        // its segment falls through to US. C4Script restarts at the empty DE
        // file, which still contributes one LF and suppresses US. Every
        // successful component gets its own leading LF and its own NUL bound.
        let assembled = tempdir().expect("assembled tempdir");
        let assembled_scenario =
            write_resilience_fixture(assembled.path(), None, "// base\0hidden base");
        std::fs::create_dir(assembled_scenario.join("ScriptDE.c"))
            .expect("create unreadable preferred component");
        std::fs::write(
            assembled_scenario.join("ScriptUS.c"),
            b"// localized US\0hidden localized tail",
        )
        .expect("write fallback localized component");
        std::fs::write(assembled_scenario.join("C4ScriptDE.c"), b"")
            .expect("write empty preferred legacy component");
        std::fs::write(
            assembled_scenario.join("C4ScriptUS.c"),
            b"// losing legacy component",
        )
        .expect("write losing legacy component");
        std::fs::write(
            assembled_scenario.join("ScriptOld.c"),
            b"// must stay excluded",
        )
        .expect("write unrelated script");
        let source = loaded_source(assembled.path(), &assembled_scenario, &["DE", "US"]);
        assert_eq!(
            clonk_script::c4_string_bytes(&source),
            b"\n// base\n// localized US\n"
        );

        // SCopySegment over an empty LanguageEx still yields one empty code:
        // Script.c is selected by both the first and second template segment.
        let empty = tempdir().expect("empty-language tempdir");
        let empty_scenario = write_resilience_fixture(empty.path(), None, "// base");
        std::fs::write(empty_scenario.join("C4Script.c"), b"// legacy")
            .expect("write empty-code legacy component");
        let source = loaded_source(empty.path(), &empty_scenario, &[]);
        assert_eq!(
            clonk_script::c4_string_bytes(&source),
            b"\n// base\n// base\n// legacy"
        );
    }

    /// Joins a default test player: the fixture's `[Player1] Crew=GOOD=1`
    /// places its crew at JOIN like C++ (C4Player::PlaceReadyCrew,
    /// C4Player.cpp:481-570). Returns the objects created by the join.
    fn join_test_player(engine: &mut Engine) -> Vec<ObjectId> {
        let before: std::collections::HashSet<ObjectId> = engine
            .snapshot()
            .objects
            .iter()
            .map(|object| object.id)
            .collect();
        engine
            .join_player(crate::JoinPlayerConfig {
                name: "Tester".to_string(),
                player_info_id: 0,
                score: 0,
                rounds: 0,
                rounds_won: 0,
                rounds_lost: 0,
                total_playing_time: 0,
                team: None,
                color_dw: 0xff0000,
                pref_color: 0,
                pref_position: 0,
                crew: Vec::new(),
                startup_player_count: 1,
                control_style: false,
                auto_context_menu: false,
            })
            .expect("join succeeds");
        engine
            .snapshot()
            .objects
            .iter()
            .map(|object| object.id)
            .filter(|id| !before.contains(id))
            .collect()
    }

    // Fair crew (the LegacyClonk default config; live-oracle probe read
    // UseFairCrew=1, strength 1000): crew physicals come from the def
    // promoted to RankByExperience(1000)=1 (C4Def.cpp:860-874,
    // C4RankSystem.cpp:226-237) — Energy = max(def, 55 * C4MaxPhysical/
    // 100) = 55000 (PromotionUpdate, C4InfoCore.cpp:207-213). GoldRush
    // live oracle: crew read 55000; bandits keep script-set temporary
    // physicals (25000).
    #[test]
    fn crew_infos_promote_physicals_by_rank_like_cpp() {
        let mut engine = Engine::with_seed(3);
        let mut clonk =
            Definition::from_script("CLNK", "Clonk", "#strict\n").expect("clonk compiles");
        clonk.set_crew_member(true);
        clonk.set_category(crate::CATEGORY_OBJECT | crate::CATEGORY_LIVING);
        clonk.set_physical(crate::PhysicalInfo {
            energy: 50_000,
            scale: 30_000,
            hangle: 30_000,
            swim: 60_000,
            fight: 50_000,
            ..crate::PhysicalInfo::default()
        });
        engine.register_definition(clonk).expect("clonk registers");

        engine
            .join_player(crate::JoinPlayerConfig {
                name: "Tester".to_string(),
                player_info_id: 0,
                score: 0,
                rounds: 0,
                rounds_won: 0,
                rounds_lost: 0,
                total_playing_time: 0,
                team: None,
                color_dw: 0xff0000,
                pref_color: 0,
                pref_position: 0,
                crew: vec![crate::player_file::CrewInfo {
                    id: "CLNK".to_string(),
                    name: "Henry".to_string(),
                    death_message: String::new(),
                    core: Default::default(),
                    rank: 1,
                    rank_name: "Ensign".to_string(),
                    experience: 120,
                    rounds: 0,
                    physical: crate::PhysicalInfo {
                        energy: 55_000,
                        scale: 30_000,
                        hangle: 30_000,
                        swim: 60_000,
                        fight: 50_000,
                        can_scale: 1,
                        can_hangle: 1,
                        can_dig: 1,
                        can_construct: 1,
                        can_chop: 1,
                        ..crate::PhysicalInfo::default()
                    },
                    death_count: 0,
                    total_playing_time: 0,
                    birthday: 0,
                    age: 0,
                    participation: 1,
                    in_action: false,
                    was_in_action: false,
                    in_action_time: 0,
                    has_died: false,
                    extra_data: Vec::new(),
                    portraits: Default::default(),
                }],
                startup_player_count: 1,
                control_style: false,
                auto_context_menu: false,
            })
            .expect("join succeeds");

        let crew = engine
            .objects
            .iter()
            .find(|object| object.definition_id == "CLNK")
            .expect("crew spawned");
        assert_eq!(
            crew.state.energy, 55_000,
            "rank-1 promotion: max(50000, 55*1000) (C4InfoCore.cpp:212)"
        );
        assert_eq!(
            crew.state.info_physical,
            Some(crate::PhysicalInfo {
                energy: 55_000,
                scale: 30_000,
                hangle: 30_000,
                swim: 60_000,
                fight: 50_000,
                can_scale: 1,
                can_hangle: 1,
                can_dig: 1,
                can_construct: 1,
                can_chop: 1,
                ..crate::PhysicalInfo::default()
            }),
            "persistent info physicals remain promoted by the info rank"
        );
        let crew_index = engine
            .find_object_index(crew.id)
            .expect("crew remains in the engine");
        assert_eq!(
            engine.object_physical(crew_index),
            crate::PhysicalInfo {
                energy: 55_000,
                scale: 33_500,
                hangle: 33_500,
                swim: 62_000,
                fight: 52_500,
                can_scale: 1,
                can_hangle: 1,
                can_dig: 1,
                can_construct: 1,
                can_chop: 1,
                ..crate::PhysicalInfo::default()
            },
            "FairCrewStrength=1000 is selected live without overwriting Info"
        );
    }

    #[test]
    fn join_player_runs_scenario_init_with_the_cpp_draw_ledger() {
        // C4Player::ScenarioInit (C4Player.cpp:670-777) consumes the synced
        // RNG in this exact order: Wealth.Evaluate (one draw,
        // C4Scenario.cpp:43-46), all-random start x/y (C4Player.cpp:745-746,
        // 16 + Random(GBack - 32) each), then PlaceReadyCrew draws one
        // Random(tx2 - tx1) per crew member (C4Player.cpp:548) with
        // FindSolidGround settling each position. Crew objects are created
        // at JOIN time — never at scenario load (C4Game::InitPlayers queues
        // CID_JoinPlr; nothing spawns crew during load).
        let dir = tempdir().expect("tempdir");
        let scenario_dir = write_resilience_fixture(dir.path(), None, "// no scenario script\n");
        std::fs::write(
            scenario_dir.join("Scenario.txt"),
            "[Head]\nTitle=Join\n\n[Definitions]\nDefinition1=Defs.c4d\n\n\
             [Landscape]\nMapWidth=64\nMapHeight=40\nMapZoom=10\n\n\
             [Player1]\nCrew=GOOD=2\nWealth=20,5,0,250\n",
        )
        .expect("write scenario core");

        let resolver = FileSystemResolver {
            roots: vec![dir.path().to_path_buf()],
        };
        let scenario =
            Scenario::load_from_path_with(&scenario_dir, &resolver).expect("scenario loads");
        let mut engine = Engine::with_seed(7);
        scenario.apply(&mut engine).expect("scenario applies");
        assert_eq!(
            engine.snapshot().objects.len(),
            0,
            "no crew at load — crew joins with the player like C++"
        );

        let mut replay = engine.rng.clone();
        let landscape = engine.landscape().expect("landscape set").clone();
        let world_width = landscape.width() as i32;
        let world_height = landscape.estimated_height();
        assert_eq!((world_width, world_height), (640, 400));

        // Replay the ledger independently.
        let expected_wealth = LegacyC4SVal::new(20, 5, 0, 250).evaluate(&mut replay);
        let mut ptx = 16 + replay.random(world_width - 32);
        let mut pty = 16 + replay.random(world_height - 32);
        if let Some((nx, ny)) = landscape.find_solid_ground(ptx, pty, 30) {
            ptx = nx;
            pty = ny;
        }
        if let Some((nx, ny)) =
            landscape.find_con_site_spot(ptx, pty, 30, 50, 400, |_, _, _, _| false)
        {
            ptx = nx;
            pty = ny;
        }
        let mut expected_positions = Vec::new();
        for _ in 0..2 {
            let mut ctx = (ptx - 30) + replay.random(60);
            let mut cty = pty;
            if let Some((nx, ny)) = landscape.find_solid_ground(ctx, cty, 0) {
                ctx = nx;
                cty = ny;
            }
            expected_positions.push(Vector2::new(ctx, cty));
        }

        let joined = engine
            .join_player(crate::JoinPlayerConfig {
                name: "Tyler".to_string(),
                player_info_id: 0,
                score: 0,
                rounds: 0,
                rounds_won: 0,
                rounds_lost: 0,
                total_playing_time: 0,
                team: None,
                color_dw: 0xf40000,
                pref_color: 3,
                pref_position: 0,
                crew: Vec::new(),
                startup_player_count: 1,
                control_style: false,
                auto_context_menu: false,
            })
            .expect("join succeeds")
            .initialized()
            .expect("join initializes");
        assert_eq!(joined.number, 0);
        assert_eq!((joined.start_x, joined.start_y), (ptx, pty));
        assert!(joined.first_base.is_none());

        // The engine consumed exactly the replayed ledger: same draw count,
        // same LCG state.
        assert_eq!(engine.rng, replay, "RNG stream stays lockstep");

        let player = engine.player(0).expect("player registered");
        assert_eq!(player.wealth(), expected_wealth);
        assert_eq!(player.color_index(), 3, "free PrefColor is taken as-is");

        let snapshot = engine.snapshot();
        let crew: Vec<_> = snapshot
            .objects
            .iter()
            .filter(|object| object.owner == 0 && object.crew_member)
            .collect();
        assert_eq!(crew.len(), 2, "two ready-crew members placed");
        let positions: Vec<_> = crew.iter().map(|object| object.position).collect();
        assert_eq!(positions, expected_positions);

        // Fresh infos: no roster, no name sources -> "Clonk", numbered by
        // MakeValidName (C4ObjectInfoList.cpp:93-101).
        let names: Vec<_> = crew
            .iter()
            .map(|object| {
                engine
                    .crew_object_info(object.id)
                    .expect("crew info recorded")
                    .name
                    .clone()
            })
            .collect();
        assert_eq!(names, vec!["Clonk".to_string(), "Clonk2".to_string()]);
    }

