    #[test]
    fn scenario_section_loads_pxs_and_mass_mover_c4b_components() {
        let dir = tempdir().expect("tempdir");
        let scenario_dir = write_resilience_fixture(dir.path(), None, "#strict\n");
        std::fs::write(
            scenario_dir.join("Scenario.txt"),
            "[Head]\nTitle=Binary section\n\n[Definitions]\nDefinition1=Defs.c4d\n\n\
             [Landscape]\nMapWidth=1,0,1,1\nMapHeight=1,0,1,1\nMapZoom=5,0,5,5\n",
        )
        .expect("write scenario core");
        let section = scenario_dir.join("SectNext.c4g");
        std::fs::create_dir_all(&section).expect("section dir");
        std::fs::write(section.join("Scenario.txt"), "[Head]\nTitle=Next\n")
            .expect("write section core");
        std::fs::write(
            section.join("Landscape.txt"),
            "map Next { seed=1; mat=Earth; tex=Rough; };",
        )
        .expect("write section landscape");
        let keep_section = scenario_dir.join("SectKeep.c4g");
        std::fs::create_dir_all(&keep_section).expect("mapless section dir");
        std::fs::write(
            keep_section.join("Scenario.txt"),
            "[Head]\nTitle=Keep current landscape\n",
        )
        .expect("write mapless section core");
        let materials = scenario_dir.join("Material.c4g");
        std::fs::create_dir_all(&materials).expect("materials dir");
        std::fs::write(materials.join("TexMap.txt"), "1=Earth-Rough\n").expect("write texmap");
        std::fs::write(
            materials.join("Earth.c4m"),
            "[Material]\nName=Earth\nDensity=100\n",
        )
        .expect("write material");
        write_test_texture(&materials, "Rough");

        let mut pxs = vec![0; 4 + crate::pxs::PXS_CHUNK_SIZE * 20];
        pxs[..4].copy_from_slice(&1i32.to_le_bytes());
        for record in pxs[4..].chunks_exact_mut(20) {
            record[..4].copy_from_slice(&(-1i32).to_le_bytes());
        }
        let record = &mut pxs[4 + 3 * 20..4 + 4 * 20];
        for (field, value) in [0i32, 98_304, -147_456, 8_192, -32_768]
            .into_iter()
            .enumerate()
        {
            record[field * 4..field * 4 + 4].copy_from_slice(&value.to_le_bytes());
        }
        std::fs::write(scenario_dir.join("PXS.c4b"), pxs.clone())
            .expect("write main PXS component");
        std::fs::write(section.join("PXS.c4b"), pxs).expect("write section PXS component");
        let mut mover = Vec::new();
        for value in [0i32, 4, 7] {
            mover.extend_from_slice(&value.to_le_bytes());
        }
        std::fs::write(scenario_dir.join("MassMover.c4b"), mover.clone())
            .expect("write main mover component");
        std::fs::write(section.join("MassMover.c4b"), mover)
            .expect("write section mover component");

        let resolver = FileSystemResolver {
            roots: vec![dir.path().to_path_buf()],
        };
        let scenario =
            Scenario::load_from_path_with(&scenario_dir, &resolver).expect("scenario loads");
        assert!(
            scenario
                .scenario_sections
                .iter()
                .find(|section| section.name.eq_ignore_ascii_case("keep"))
                .expect("mapless section discovered")
                .landscape
                .is_none(),
            "section core values alone do not set C++ LandscapeLoaded"
        );
        let mut engine = Engine::with_seed(0);
        scenario.apply(&mut engine).expect("scenario applies");
        assert!(engine.pxs_system.peek_slot(0, 3).is_some());
        assert_eq!(
            engine.mass_movers.slot(0).map(|mover| (mover.x, mover.y)),
            Some((4, 7))
        );
        engine.pxs_system.note_executed();
        assert!(engine
            .load_scenario_section("Keep", 0, Vec::new())
            .expect("mapless section load succeeds"));
        assert!(engine.pxs_system.peek_slot(0, 3).is_some());
        assert_eq!(
            engine.mass_movers.slot(0).map(|mover| (mover.x, mover.y)),
            Some((4, 7))
        );
        assert_eq!(engine.pxs_system.execute_count(), 1);
        assert!(engine
            .load_scenario_section("Next", 0, Vec::new())
            .expect("section load succeeds"));

        let pixel = engine
            .pxs_system
            .peek_slot(0, 3)
            .expect("PXS slot restores");
        assert_eq!(pixel.mat.index(), 0);
        assert_eq!(
            [
                pixel.x.val(),
                pixel.y.val(),
                pixel.xdir.val(),
                pixel.ydir.val()
            ],
            [98_304, -147_456, 8_192, -32_768]
        );
        let mover = engine.mass_movers.slot(0).expect("mover slot restores");
        assert_eq!((mover.mat.index(), mover.x, mover.y), (0, 4, 7));
        assert_eq!(engine.mass_movers.count(), 1);
        assert_eq!(engine.mass_movers.create_ptr(), 0);
        assert_eq!(
            engine.pxs_system.execute_count(),
            1,
            "PXS Load leaves Count intact"
        );
    }

    #[test]
    fn scenario_section_s2_reuses_retained_main_template_and_default_map() {
        // CreateMapS2 appends a section Landscape.txt to the live creator.
        // Consequently the section can resolve a main-section template and
        // its new map keeps the creator's construction-time dimensions,
        // rather than evaluating the section's MapWidth/MapHeight values.
        let dir = tempdir().expect("tempdir");
        let scenario_dir = write_resilience_fixture(dir.path(), None, "// no script\n");
        std::fs::write(
            scenario_dir.join("Scenario.txt"),
            "[Head]\nTitle=Retained section creator\n\n\
             [Definitions]\nDefinition1=Defs.c4d\n\n\
             [Landscape]\n\
             MapWidth=8,0,8,8\n\
             MapHeight=1,0,1,1\n\
             MapZoom=5,0,5,5\n\
             Gravity=100,0,100,100\n\
             AutoScanSideOpen=0\n\
             KeepMapCreator=1\n",
        )
        .expect("write scenario core");
        std::fs::write(
            scenario_dir.join("Landscape.txt"),
            "overlay RetainedBand { mat=Earth; tex=Rough; sub=0; \
             wdt=50; hgt=100; seed=7; }; \
             map Main { seed=11; RetainedBand; };",
        )
        .expect("write main landscape script");

        let section = scenario_dir.join("SectNext.c4g");
        std::fs::create_dir_all(&section).expect("section dir");
        std::fs::write(
            section.join("Scenario.txt"),
            "[Head]\nTitle=Next\n\n\
             [Landscape]\n\
             MapWidth=3,0,3,3\n\
             MapHeight=4,0,4,4\n\
             MapZoom=5,0,5,5\n\
             KeepMapCreator=1\n",
        )
        .expect("write section core");
        std::fs::write(
            section.join("Landscape.txt"),
            "map Next { seed=13; RetainedBand { x=50; }; };",
        )
        .expect("write section landscape script");

        let materials = scenario_dir.join("Material.c4g");
        std::fs::create_dir_all(&materials).expect("materials dir");
        std::fs::write(materials.join("TexMap.txt"), "1=Earth-Rough\n").expect("write texmap");
        std::fs::write(
            materials.join("Earth.c4m"),
            "[Material]\nName=Earth\nDensity=100\nShape=0\n",
        )
        .expect("write material");
        write_test_texture(&materials, "Rough");

        let resolver = FileSystemResolver {
            roots: vec![dir.path().to_path_buf()],
        };
        let scenario =
            Scenario::load_from_path_with(&scenario_dir, &resolver).expect("scenario loads");
        let mut engine = Engine::with_seed(0);
        scenario.apply(&mut engine).expect("scenario applies");

        let main_raster = engine
            .landscape()
            .and_then(Landscape::raster_state)
            .expect("main raster state");
        let main_map = main_raster.map().expect("main retained map");
        assert_eq!((main_map.width, main_map.height), (8, 1));
        assert_eq!(main_map.indices, vec![1, 1, 1, 1, 0, 0, 0, 0]);
        assert!(
            main_raster.map_creator().is_some(),
            "main KeepMapCreator retains the creator for section overloads"
        );

        engine.rng.random(17);
        engine.rng.rnd3();
        assert!(engine
            .load_scenario_section("Next", 0, Vec::new())
            .expect("section load succeeds"));

        let landscape = engine.landscape().expect("section landscape");
        let raster = landscape.raster_state().expect("section raster state");
        let map = raster.map().expect("section retained map");
        assert_eq!(
            (map.width, map.height),
            (8, 1),
            "the retained DefaultMap wins over section dimensions 3x4"
        );
        assert_eq!(map.indices, vec![0, 0, 0, 0, 1, 1, 1, 1]);
        assert_eq!(
            (landscape.width(), landscape.estimated_height()),
            (100, 100)
        );
        assert_eq!(landscape.grid_byte_at(19, 2), Some(0));
        assert_eq!(landscape.grid_byte_at(20, 2), Some(1));
        assert_eq!(landscape.grid_byte_at(39, 2), Some(1));
        assert_eq!(landscape.grid_byte_at(40, 2), Some(0));
        let mut retained_creator = raster
            .map_creator()
            .expect("the appended creator remains live under KeepMapCreator")
            .clone();
        let mut classifier = MapPixelClassifier::from_runtime_state(raster.texmap().clone());
        let mut probe_rng = crate::rng::LcgRng::seed_from_u64(41);
        let probe_count = probe_rng.count;
        let retained_main = crate::map_creator_s2::render_named_s2_map(
            &mut retained_creator,
            "Main",
            &mut classifier,
            8,
            1,
            &mut probe_rng,
        )
        .expect("the original named map remains in the creator");
        assert_eq!(retained_main.indices, vec![1, 1, 1, 1, 0, 0, 0, 0]);
        let appended_next = crate::map_creator_s2::render_named_s2_map(
            &mut retained_creator,
            "Next",
            &mut classifier,
            8,
            1,
            &mut probe_rng,
        )
        .expect("the section map was appended to the creator");
        assert_eq!(appended_next.indices, vec![0, 0, 0, 0, 1, 1, 1, 1]);
        assert_eq!(
            probe_rng.count, probe_count,
            "fixed retained nodes consume no RNG when re-evaluated"
        );

        let mut expected = crate::rng::LcgRng::seed_from_u64(0);
        let _ = expected.random(1);
        expected.trace = engine.rng.trace;
        assert_eq!(engine.rng.count, 501);
        assert_eq!(engine.rng.rnd3_ptr(), 0);
        assert_eq!(
            engine.rng, expected,
            "the second FixRandom hides map creation and gravity consumes one draw"
        );
    }

    #[test]
    fn scenario_section_script_algorithm_uses_live_host_and_preserves_globals() {
        let dir = tempdir().expect("tempdir");
        let scenario_dir = write_resilience_fixture(
            dir.path(),
            None,
            "#strict\nstatic section_calls;\n\
             func ScriptAlgoLive(x, y, a, b) {\n\
                 if (!section_calls) section_calls = 0;\n\
                 section_calls++;\n\
                 Random(7);\n\
                 return y == 0 && a == 5 && b == 9\n\
                     && x == (section_calls - 1) * 100;\n\
             }\n",
        );
        std::fs::write(
            scenario_dir.join("Scenario.txt"),
            "[Head]\nTitle=Section ScriptAlgo\n\n[Definitions]\nDefinition1=Defs.c4d\n\n\
             [Landscape]\nMapWidth=2,0,2,2\nMapHeight=1,0,1,1\n\
             MapZoom=5,0,5,5\nKeepMapCreator=1\n",
        )
        .expect("write main core");
        std::fs::write(
            scenario_dir.join("Landscape.txt"),
            "map Main { seed=1; wdt=2px; hgt=1px; };\n",
        )
        .expect("write main landscape");

        let section = scenario_dir.join("SectNext.c4g");
        std::fs::create_dir_all(&section).expect("section dir");
        std::fs::write(
            section.join("Scenario.txt"),
            "[Head]\nTitle=Next\n\n[Landscape]\nMapZoom=5,0,5,5\nKeepMapCreator=1\n",
        )
        .expect("write section core");
        std::fs::write(
            section.join("Landscape.txt"),
            "map Next { seed=2; wdt=2px; hgt=1px;\n\
               overlay Live { seed=3; algo=script; a=5; b=9;\n\
                              mat=Earth; tex=Rough; sub=0; };\n\
             };\n",
        )
        .expect("write section landscape");

        let materials = scenario_dir.join("Material.c4g");
        std::fs::create_dir_all(&materials).expect("materials dir");
        std::fs::write(materials.join("TexMap.txt"), "1=Earth-Rough\n").expect("write texmap");
        std::fs::write(
            materials.join("Earth.c4m"),
            "[Material]\nName=Earth\nDensity=100\n",
        )
        .expect("write material");
        write_test_texture(&materials, "Rough");

        let resolver = FileSystemResolver {
            roots: vec![dir.path().to_path_buf()],
        };
        let scenario =
            Scenario::load_from_path_with(&scenario_dir, &resolver).expect("scenario loads");
        let mut engine = Engine::with_seed(0);
        scenario.apply(&mut engine).expect("scenario applies");
        assert!(engine
            .load_scenario_section("Next", 0, Vec::new())
            .expect("section load succeeds"));

        assert_eq!(
            engine
                .landscape()
                .and_then(Landscape::raster_state)
                .and_then(LandscapeRasterState::map)
                .map(|map| map.indices),
            Some(vec![1, 1]),
            "the section map executes ScriptAlgoLive in row-major order"
        );
        assert_eq!(
            engine
                .script_globals
                .borrow()
                .get("section_calls")
                .map(|cell| cell.borrow().clone()),
            Some(clonk_script::Value::Int(2)),
            "section restore keeps globals mutated by live ScriptAlgo calls"
        );
    }

    #[test]
    fn ancestor_texmap_overloads_global_water_material() {
        // C4Game::InitMaterialTexture walks the ordered NRT_Material chain
        // while each source's OverloadMaterials/OverloadTextures flags admit
        // the next one (C4Game.cpp:901-977). C4MaterialMap::Load prepends new
        // names while earlier sources win collisions (C4Material.cpp:263-299).
        // Hazard/CTF_DeepSea has this exact shape: its enclosing package owns
        // TexMap slot 3=Water-Liquid but only the final global Material.c4g
        // supplies Water.c4m. Missing that second source turns map byte 0x83
        // into sky, so C4Game::PlaceAnimal cannot place either shark.
        let dir = tempdir().expect("tempdir");

        let defs_root = dir.path().join("Defs.c4d");
        let good = defs_root.join("Good.c4d");
        std::fs::create_dir_all(&good).expect("definition dir");
        std::fs::write(
            good.join("DefCore.txt"),
            "[DefCore]\nid=GOOD\nName=Good\nCategory=0\nCrewMember=0\n",
        )
        .expect("write defcore");
        write_test_definition_graphics(&good);

        let package = dir.path().join("Pack.c4f");
        let scenario_dir = package.join("Deep.c4s");
        std::fs::create_dir_all(&scenario_dir).expect("scenario dir");
        std::fs::write(
            scenario_dir.join("Scenario.txt"),
            "[Head]\nTitle=Deep\n\n[Definitions]\nDefinition1=Defs.c4d\n\n\
             [Landscape]\nMapZoom=10\n",
        )
        .expect("write scenario core");
        std::fs::write(
            scenario_dir.join("Landscape.bmp"),
            encode_indexed_bmp(&[&[0x83, 0x83], &[0x83, 0x83]]),
        )
        .expect("write map");

        let package_materials = package.join("Material.c4g");
        std::fs::create_dir_all(&package_materials).expect("package materials");
        std::fs::write(
            package_materials.join("TexMap.txt"),
            "OverloadMaterials\nOverloadTextures\n3=Water-Liquid\n4=PackStone-Smooth\n",
        )
        .expect("write package texmap");
        // Keep this source non-empty: reaching the global Water material must
        // be caused by OverloadMaterials, not the C++ zero-material fallback.
        std::fs::write(
            package_materials.join("PackStone.c4m"),
            "[Material]\nName=PackStone\nDensity=100\n",
        )
        .expect("write package material");
        write_test_texture(&package_materials, "Liquid");
        write_test_texture(&package_materials, "Smooth");

        let global_materials = dir.path().join("Material.c4g");
        std::fs::create_dir_all(&global_materials).expect("global materials");
        // Later C++ material resources must carry TexMap.txt so LoadFlags can
        // admit their contents; this table is not used for slot mappings.
        std::fs::write(global_materials.join("TexMap.txt"), "# global table\n")
            .expect("write global texmap");
        std::fs::write(
            global_materials.join("Water.c4m"),
            "[Material]\nName=Water\nDensity=25\n",
        )
        .expect("write global water");

        // Resolver order mirrors DeepSea: enclosing package, then content
        // root. There is deliberately no scenario-local Material.c4g.
        let resolver = FileSystemResolver {
            roots: vec![package, dir.path().to_path_buf()],
        };
        let scenario =
            Scenario::load_from_path_with(&scenario_dir, &resolver).expect("scenario loads");
        let mut engine = Engine::with_seed(0);
        scenario.apply(&mut engine).expect("scenario applies");
        let landscape = engine.landscape().expect("landscape loaded");

        assert_eq!(
            landscape.grid_byte_at(5, 5),
            Some(0x83),
            "the package TexMap byte survives with its IFT bit"
        );
        assert!(
            landscape.is_liquid_at(5, 5),
            "global Water.c4m supplies slot 3 density through OverloadMaterials"
        );
        assert!(landscape.is_ift_at(5, 5));
    }

    #[test]
    fn same_group_duplicate_materials_retain_slots_across_overload_chain() {
        let dir = tempdir().expect("tempdir");
        let scenario_dir = dir.path().join("DuplicateMaterials.c4s");
        let local = scenario_dir.join("Material.c4g");
        std::fs::create_dir_all(&local).expect("local materials dir");
        std::fs::write(
            local.join("TexMap.txt"),
            "OverloadMaterials\nOverloadTextures\n",
        )
        .expect("write local texmap");
        for (file, name, density, overlay) in [
            ("A.c4m", "Dup", 10, "Rough"),
            ("B.c4m", "dUp", 20, "Smooth"),
            ("C.c4m", "LocalOnly", 30, "Rough"),
        ] {
            std::fs::write(
                local.join(file),
                format!("[Material]\nName={name}\nDensity={density}\nTextureOverlay={overlay}\n"),
            )
            .expect("write local material");
        }
        write_test_texture(&local, "Rough");
        write_test_texture(&local, "Smooth");

        let installed_root = dir.path().join("Installed");
        let installed = installed_root.join("Material.c4g");
        std::fs::create_dir_all(&installed).expect("installed materials dir");
        std::fs::write(installed.join("TexMap.txt"), "# installed\n")
            .expect("write installed texmap");
        std::fs::write(
            installed.join("Global.c4m"),
            "[Material]\nName=Global\nDensity=40\nTextureOverlay=Smooth\n",
        )
        .expect("write installed material");

        let group = Group::open(&scenario_dir).expect("scenario group opens");
        let resolver = FileSystemResolver {
            roots: vec![installed_root],
        };
        let classifier = build_map_pixel_classifier(&group, &resolver)
            .expect("classifier load succeeds")
            .expect("local texmap builds classifier");
        let library = classifier.material_library().expect("materials loaded");
        assert_eq!(
            library
                .iter()
                .map(|material| material.name())
                .collect::<Vec<_>>(),
            vec!["Global", "Dup", "dUp", "LocalOnly"]
        );
        assert_eq!(
            library
                .get("dup")
                .and_then(|material| material.int("density")),
            Some(10),
            "name lookup resolves the first same-load duplicate"
        );

        let materials = crate::MaterialSet::from_resource_library(library);
        assert_eq!(materials.len(), 4, "duplicates retain numeric slots");
        assert_eq!(materials.id_of("DUP").map(|id| id.index()), Some(1));
        assert_eq!(
            materials
                .iter()
                .map(|material| material.name())
                .collect::<Vec<_>>(),
            vec!["Global", "Dup", "dUp", "LocalOnly"]
        );

        let duplicate_defaults = classifier
            .state
            .default_material_entries
            .iter()
            .filter(|(name, _)| name.eq_ignore_ascii_case("dup"))
            .map(|(_, slot)| *slot)
            .collect::<Vec<_>>();
        assert_eq!(duplicate_defaults.len(), 2);
        assert_eq!(
            classifier.state.default_material_entry("dup"),
            Some(duplicate_defaults[0])
        );
        assert_eq!(
            classifier.state.default_material_entry_by_index(1),
            Some(duplicate_defaults[0])
        );
        assert_eq!(
            classifier.state.default_material_entry_by_index(2),
            Some(duplicate_defaults[1]),
            "numeric material lookup keeps a later same-name material's own DefaultMatTex"
        );
        assert_eq!(
            classifier.state.match_texture_names[usize::from(duplicate_defaults[0])].as_deref(),
            Some("Rough")
        );
        assert_eq!(
            classifier.state.match_texture_names[usize::from(duplicate_defaults[1])].as_deref(),
            Some("Smooth")
        );
    }

    #[test]
    fn material_and_texture_names_use_c4m_max_name_bytes() {
        let material_prefix = b"MaterialPrefix\x80";
        let texture_prefix = b"TexturePrefixX\x81";
        assert_eq!(material_prefix.len(), 15);
        assert_eq!(texture_prefix.len(), 15);

        let mut material_long_a = material_prefix.to_vec();
        material_long_a.extend_from_slice(b"First");
        let mut material_long_b = material_prefix.to_vec();
        material_long_b.extend_from_slice(b"Second");
        let mut texture_long_a = texture_prefix.to_vec();
        texture_long_a.extend_from_slice(b"One");
        let mut texture_long_b = texture_prefix.to_vec();
        texture_long_b.extend_from_slice(b"Two");

        let material_source = |name: &[u8], density: i32| {
            let mut source = b"[Material]\nName=".to_vec();
            source.extend_from_slice(name);
            source.extend_from_slice(format!("\nDensity={density}\nTextureOverlay=").as_bytes());
            source.extend_from_slice(texture_prefix);
            source.push(b'\n');
            source
        };
        let mut texmap_source = b"20=".to_vec();
        texmap_source.extend_from_slice(material_prefix);
        texmap_source.push(b'-');
        texmap_source.extend_from_slice(texture_prefix);
        texmap_source.extend_from_slice(b"\n21=");
        texmap_source.extend_from_slice(&material_long_a);
        texmap_source.push(b'-');
        texmap_source.extend_from_slice(&texture_long_a);
        texmap_source.push(b'\n');

        let parsed_texmap = clonk_resources::texmap::TextureMap::parse_bytes(&texmap_source);
        assert_eq!(
            clonk_script::c4_string_bytes(&parsed_texmap.entry(21).unwrap().material),
            material_long_a,
            "TexMap names remain raw and unbounded"
        );
        assert_eq!(
            clonk_script::c4_string_bytes(&parsed_texmap.entry(21).unwrap().texture),
            texture_long_a,
            "non-UTF-8 TexMap bytes survive without replacement"
        );

        let mut materials = clonk_resources::MutableGroup::new("Material.c4g");
        materials
            .add_file("A.c4m", material_source(&material_long_a, 61))
            .unwrap();
        materials
            .add_file("B.c4m", material_source(&material_long_b, 72))
            .unwrap();
        materials.add_file("TexMap.txt", texmap_source).unwrap();
        let texture_bitmap = encode_indexed_bmp(&[&[0u8]]);
        for stem in [&texture_long_a, &texture_long_b] {
            let mut filename = stem.to_vec();
            filename.extend_from_slice(b".bmp");
            materials
                .add_file_bytes_with_metadata(filename, texture_bitmap.clone(), 1, false)
                .unwrap();
        }
        materials
            .add_file(
                "Mislabeled.bmp",
                include_bytes!("../../../content/Material.c4g/Snow.png").to_vec(),
            )
            .unwrap();

        let mut scenario = clonk_resources::MutableGroup::new("ByteNames.c4s");
        scenario
            .add_packed_child_with_metadata(
                "Material.c4g",
                materials.pack_raw().unwrap(),
                0,
                1,
                false,
            )
            .unwrap();
        let group =
            Group::from_raw_memory(PathBuf::from("ByteNames.c4s"), scenario.pack_raw().unwrap())
                .unwrap();
        let classifier =
            build_map_pixel_classifier(&group, &FileSystemResolver { roots: Vec::new() })
                .unwrap()
                .unwrap();
        let library = classifier.material_library().unwrap();
        let names = library
            .iter()
            .map(|material| clonk_script::c4_string_bytes(material.name()))
            .collect::<Vec<_>>();
        assert_eq!(
            names,
            vec![material_prefix.to_vec(), material_prefix.to_vec()]
        );
        for material in library.iter() {
            assert_eq!(
                material.value("Name").map(clonk_script::c4_string_bytes),
                Some(material_prefix.to_vec()),
                "compiled Name reflection matches the fixed live core"
            );
        }
        assert_eq!(
            library
                .get(&clonk_script::c4_string_from_bytes(material_prefix))
                .and_then(|material| material.int("Density")),
            Some(61),
            "the first same-load fixed-name collision owns name lookup"
        );
        assert!(
            library
                .get(&clonk_script::c4_string_from_bytes(&material_long_a))
                .is_none(),
            "whole-name lookup does not prefix-match a fixed identity"
        );

        assert_eq!(
            classifier
                .state
                .texture_inventory
                .iter()
                .map(|name| clonk_script::c4_string_bytes(name))
                .collect::<Vec<_>>(),
            vec![texture_prefix.to_vec(), texture_prefix.to_vec()],
            "long candidates admit before truncation, but a PNG payload named BMP is rejected"
        );
        assert_eq!(
            classifier.state.densities[20], 61,
            "the fixed TexMap identity resolves the first material collision"
        );
        assert!(classifier.state.material_names[20].is_some());
        assert!(
            classifier.state.material_names[21].is_none(),
            "an unbounded TexMap pair does not prefix-match fixed identities"
        );
    }

    #[test]
    fn scenario_local_material_reaction_overrides_installed_material_like_cpp() {
        // Tutorial10's local FlyAshes.c4m adds a Convert/SemiSolid→Sky
        // reaction so volcanic ash vanishes on DuroLava instead of sinking
        // beneath it and isolating the pump's source endpoint. C++ loads the
        // scenario material group before the installed group; the first
        // definition of a duplicate material name wins (C4Game.cpp:901-977,
        // C4Material.cpp:263-299).
        let dir = tempdir().expect("tempdir");

        let definition = dir.path().join("Defs.c4d/Good.c4d");
        std::fs::create_dir_all(&definition).expect("definition dir");
        std::fs::write(
            definition.join("DefCore.txt"),
            "[DefCore]\nid=GOOD\nName=Good\nCategory=0\nCrewMember=0\n",
        )
        .expect("write definition");
        write_test_definition_graphics(&definition);

        let scenario_dir = dir.path().join("Tutorial10.c4s");
        std::fs::create_dir_all(&scenario_dir).expect("scenario dir");
        std::fs::write(
            scenario_dir.join("Scenario.txt"),
            "[Head]\nTitle=Tutorial10 material override\n\n\
             [Definitions]\nDefinition1=Defs.c4d\n\n\
             [Landscape]\nMapZoom=10\n",
        )
        .expect("write scenario core");
        std::fs::write(
            scenario_dir.join("Landscape.bmp"),
            encode_indexed_bmp(&[&[24, 59], &[24, 59]]),
        )
        .expect("write landscape");

        let local_materials = scenario_dir.join("Material.c4g");
        std::fs::create_dir_all(&local_materials).expect("local materials");
        std::fs::write(
            local_materials.join("TexMap.txt"),
            "OverloadMaterials\nOverloadTextures\n24=DuroLava-Liquid\n59=FlyAshes-Smooth\n",
        )
        .expect("write local texmap");
        std::fs::write(
            local_materials.join("FlyAshes.c4m"),
            "[Material]\nName=FlyAshes\nDensity=50\n\n\
             [Reaction]\nType=Convert\nTargetSpec=SemiSolid\nExecMask=-1\nConvertMat=Sky\n",
        )
        .expect("write local FlyAshes override");

        let installed_materials = dir.path().join("Material.c4g");
        std::fs::create_dir_all(&installed_materials).expect("installed materials");
        std::fs::write(
            installed_materials.join("TexMap.txt"),
            "# installed table\n",
        )
        .expect("write installed texmap");
        std::fs::write(
            installed_materials.join("FlyAshes.c4m"),
            "[Material]\nName=FlyAshes\nDensity=50\n",
        )
        .expect("write installed FlyAshes");
        std::fs::write(
            installed_materials.join("DuroLava.c4m"),
            "[Material]\nName=DuroLava\nDensity=25\n",
        )
        .expect("write installed DuroLava");

        let resolver = FileSystemResolver {
            roots: vec![dir.path().to_path_buf()],
        };
        let scenario =
            Scenario::load_from_path_with(&scenario_dir, &resolver).expect("scenario loads");
        let installed_group = Group::open(&installed_materials).expect("installed group opens");
        let installed_library = clonk_resources::MaterialLibrary::from_group(&installed_group)
            .expect("installed materials load");
        let mut engine = Engine::with_seed(0);
        engine.configure_materials_from_library(&installed_library);
        scenario.apply(&mut engine).expect("scenario applies");

        let fly_ashes = engine
            .materials()
            .id_of("FlyAshes")
            .expect("FlyAshes is loaded");
        let duro_lava = engine
            .materials()
            .id_of("DuroLava")
            .expect("DuroLava is loaded from the admitted installed group");
        let reaction = engine
            .materials()
            .reaction(Some(fly_ashes), Some(duro_lava));
        assert!(
            reaction.user_defined,
            "the local reaction overrides defaults"
        );
        assert_eq!(
            reaction.kind,
            crate::material::MaterialReactionKind::Convert {
                target: None,
                depth: None,
            },
            "Tutorial10 FlyAshes converts to Sky on semi-solid DuroLava"
        );
    }

    #[test]
    fn legacy_scenario_threads_border_open_keys_into_the_landscape() {
        // C4Landscape::ScenarioInit (C4Landscape.cpp:67-73) copies the
        // Scenario.txt LeftOpen/RightOpen/TopOpen/BottomOpen keys onto the
        // landscape; AutoScanSideOpen=0 keeps the explicit side values.
        let dir = tempdir().expect("tempdir");
        let defs_root = dir.path().join("Defs.c4d");
        let good = defs_root.join("Good.c4d");
        std::fs::create_dir_all(&good).expect("definition dir");
        std::fs::write(
            good.join("DefCore.txt"),
            "[DefCore]\nid=GOOD\nName=Good\nCategory=0\nCrewMember=0\n",
        )
        .expect("write defcore");
        std::fs::write(good.join("Script.c"), "// fine\n").expect("write script");
        write_test_definition_graphics(&good);

        let scenario_dir = dir.path().join("Borders.c4s");
        std::fs::create_dir_all(&scenario_dir).expect("scenario dir");
        std::fs::write(
            scenario_dir.join("Scenario.txt"),
            "[Head]\nTitle=Borders\n\n[Definitions]\nDefinition1=Defs.c4d\n\n\
             [Landscape]\nMapZoom=10\nTopOpen=0\nBottomOpen=1\nLeftOpen=7\nRightOpen=9\nAutoScanSideOpen=0\n",
        )
        .expect("write scenario core");
        std::fs::write(
            scenario_dir.join("Landscape.bmp"),
            encode_indexed_bmp(&[
                &[0, 0, 0, 0],
                &[0, 0, 0, 0],
                &[30, 30, 30, 0],
                &[30, 30, 30, 30],
            ]),
        )
        .expect("write map");
        let materials = scenario_dir.join("Material.c4g");
        std::fs::create_dir_all(&materials).expect("materials dir");
        std::fs::write(materials.join("TexMap.txt"), "# table\n30=Earth-Smooth\n")
            .expect("write texmap");
        std::fs::write(
            materials.join("Earth.c4m"),
            "[Material]\nName=Earth\nDensity=100\n",
        )
        .expect("write earth");

        let resolver = FileSystemResolver {
            roots: vec![dir.path().to_path_buf()],
        };
        let scenario =
            Scenario::load_from_path_with(&scenario_dir, &resolver).expect("scenario loads");
        let mut engine = Engine::with_seed(0);
        scenario.apply(&mut engine).expect("scenario applies");
        let landscape = engine.landscape().expect("landscape loaded");
        assert_eq!(landscape.left_open(), 7);
        assert_eq!(landscape.right_open(), 9);
        assert!(!landscape.top_open());
        assert!(landscape.bottom_open());
    }

    #[test]
    fn cpp_runtime_landscape_preseeds_map_and_savegame_fields_override_scenario_init() {
        let dir = tempdir().expect("tempdir");
        let scenario_dir = write_resilience_fixture(dir.path(), None, "// no script\n");
        std::fs::write(
            scenario_dir.join("Scenario.txt"),
            "[Head]\nTitle=Runtime Landscape\nSaveGame=1\n\n\
             [Definitions]\nDefinition1=Defs.c4d\n\n\
             [Landscape]\nMapZoom=5\nGravity=120\nTopOpen=1\nBottomOpen=0\nLeftOpen=7\nRightOpen=9\nAutoScanSideOpen=0\n",
        )
        .expect("write save core");
        std::fs::write(
            scenario_dir.join("Game.txt"),
            "[Landscape]\r\nMapSeed=-7\r\nLeftOpen=-1\r\nRightOpen=42\r\nBottomOpen=true\r\nMatModulation=4278255360\r\n",
        )
        .expect("write C++ runtime block");
        std::fs::write(
            scenario_dir.join("Map.bmp"),
            encode_indexed_bmp(&[&[0, 0, 0], &[30, 30, 30]]),
        )
        .expect("write static map");
        let materials = scenario_dir.join("Material.c4g");
        std::fs::create_dir_all(&materials).expect("materials dir");
        std::fs::write(materials.join("TexMap.txt"), "30=Earth-Smooth\n").expect("write texmap");
        std::fs::write(
            materials.join("Earth.c4m"),
            "[Material]\nName=Earth\nColor=1,2,3,4,5,6,7,8,9\nDensity=100\nShape=2\n",
        )
        .expect("write earth");
        write_test_texture(&materials, "Smooth");

        let resolver = FileSystemResolver {
            roots: vec![dir.path().to_path_buf()],
        };
        let scenario =
            Scenario::load_from_path_with(&scenario_dir, &resolver).expect("savegame loads");
        let mut engine = Engine::with_seed(0);
        scenario.apply(&mut engine).expect("savegame applies");

        let landscape = engine.landscape().expect("landscape restored");
        assert_eq!(landscape.map_seed(), -7);
        assert_eq!(landscape.left_open(), -1);
        assert_eq!(landscape.right_open(), 42);
        assert!(
            !landscape.top_open(),
            "omitted runtime TopOpen defaults false"
        );
        assert!(landscape.bottom_open());
        assert_eq!(landscape.modulation(), 4_278_255_360);
        assert_eq!(
            landscape.mode(),
            LANDSCAPE_MODE_STATIC,
            "omitted runtime Mode is inferred during Init"
        );
        let mut shapes = vec![None; 128];
        shapes[30] = Some(crate::chunky::ChunkShape::Smooth);
        let indices = [0, 0, 0, 30, 30, 30];
        let expected =
            crate::chunky::synthesize_landscape(&indices, 3, 2, 5, -7, &shapes).into_bytes();
        let generated_seed = map_seed_from_random_seed(0);
        let wrong = crate::chunky::synthesize_landscape(&indices, 3, 2, 5, generated_seed, &shapes)
            .into_bytes();
        assert_ne!(expected, wrong, "fixture must distinguish the runtime seed");
        let grid = landscape.pixel_grid().expect("static Surface8 restored");
        for row in 0..10 {
            assert_eq!(
                &grid.bytes()[row * 100..row * 100 + 15],
                &expected[row * 15..row * 15 + 15],
                "runtime MapSeed must affect ChunkOZoom before synthesis"
            );
        }
        assert_eq!(
            engine.physics().gravity_raw(),
            crate::network_game_data::LANDSCAPE_DEFAULT_GRAVITY_RAW,
            "omitted runtime Gravity defaults to raw FIXED100(20)"
        );
        assert_eq!(
            engine.physics().gravity,
            100,
            "GetGravity projection restores too"
        );
        let mut edited_physics = engine.physics();
        edited_physics.gravity = 200;
        assert_eq!(
            edited_physics.gravity_raw(),
            (crate::math::fixed100(200) / 5).val(),
            "a copied value immediately honors its edited public projection"
        );
        assert!(
            !serde_json::to_string(&edited_physics)
                .unwrap()
                .contains("gravity_raw"),
            "a stale hidden override is not serialized"
        );
        engine.set_physics(edited_physics);
        assert_eq!(
            engine.physics().gravity_raw(),
            (crate::math::fixed100(200) / 5).val()
        );

        // Initial network dynamics carry exact Game.txt data without turning
        // Scenario.txt into a savegame. MapSeed/Mode/Modulation are compiled
        // before Init, while ScenarioInit still owns gravity and borders.
        let core = std::fs::read_to_string(scenario_dir.join("Scenario.txt")).unwrap();
        std::fs::write(
            scenario_dir.join("Scenario.txt"),
            core.replace("SaveGame=1\n", "SaveGame=0\n"),
        )
        .unwrap();
        let scenario =
            Scenario::load_from_path_with(&scenario_dir, &resolver).expect("initial dynamic loads");
        let mut initial = Engine::with_seed(0);
        scenario
            .apply(&mut initial)
            .expect("initial dynamic applies");
        let landscape = initial.landscape().unwrap();
        assert_eq!(landscape.map_seed(), -7);
        assert_eq!(landscape.mode(), LANDSCAPE_MODE_STATIC);
        assert_eq!(landscape.modulation(), 4_278_255_360);
        assert_eq!((landscape.left_open(), landscape.right_open()), (7, 9));
        assert!(landscape.top_open());
        assert!(!landscape.bottom_open());
        assert_eq!(initial.physics().gravity, 120);
    }

